import assert from 'node:assert/strict';
import path from 'node:path';
import {loadWorkspaceOmpSdk} from '../../server/workspace-omp-session.mjs';
import {workspaceOmpPaths} from '../../server/workspace-omp-runtime.mjs';
globalThis.fetch=async()=>{throw Error('NETWORK_FORBIDDEN');};
const file=process.argv[2];assert.ok(file?.startsWith('/tmp/enterprise-context-host-')&&file.endsWith('.jsonl'));
const sdk=await loadWorkspaceOmpSdk(workspaceOmpPaths({}).packageRoot),manager=await sdk.SessionManager.open(file,path.dirname(file),undefined,{throwIfMissing:true});
const last=manager.getBranch().filter(row=>row.type==='message').at(-1);assert.ok(last);
manager.appendCompaction('SYNTHETIC_DOC_SUMMARY_RETAINS_ORIGINAL_SOURCE_OBLIGATIONS',undefined,last.id,100,{fromExtension:true});await manager.flush();
const privateMessages=manager.buildSessionContext().messages.filter(row=>row.toolName?.startsWith('workspace_enterprise_context_')).length;
assert.equal(privateMessages,0);console.log(JSON.stringify({privateMessages,realModelRequests:0,syntheticSummary:true}));
